window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-19ed18a3eb8973de"]={"versions": [{"id": "FIG-19ed18a3eb8973de", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm zur Darstellung des logischen Speicher-Layouts und der Adressierung von Datensätzen (Dataset NVRAM Block) im AUTOSAR NVRAM Manager (NvM). Das Schaubild veranschaulicht die logische Gruppierung und Indizierung der optionalen ROM-Block-Datenbereiche eines Dataset-Blocks, losgelöst von der physikalischen Speicherorganisation im nichtflüchtigen Speicher.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>ROM block data area NVM_NV_BLOCK_NUM (opt)</strong>: Erster optionaler Festwertspeicherbereich (Default-/Fallback-Daten) des Dataset-Blocks, adressiert über den Startindex <code>NVM_NV_BLOCK_NUM</code>.</li>\n<li><strong>ROM block data area (NVM_NV_BLOCK_NUM+NVM_ROM_BLOCK_NUM-1) (opt)</strong>: Letzter optionaler ROM-Datenbereich des Dataset-Blocks.</li>\n<li><strong>Indexspanne (<code>index NVM_NV_BLOCK_NUM to NVM_NV_BLOCK_NUM+NVM_ROM_BLOCK_NUM-1</code>)</strong>: Vertikaler Maß- bzw. Adressierungsvektor, der den gültigen Indexbereich für die Adressierung der ROM-Datensätze über die NvM-Dataset-Schnittstelle definiert.</li>\n<li><strong>Auslassungspunkte (<code>. . .</code>)</strong>: Symbolisieren dazwischenliegende, fortlaufend nummerierte ROM-Blöcke.</li>\n<li><strong>Gestrichelter Rahmen</strong>: Logische Umklammerung bzw. Clusterung der optionalen ROM-Blöcke innerhalb des Gesamt-Dataset-NVRAM-Blocks.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Adressierung eines spezifischen ROM-Datensatzes über den Datensatz-Index (Dataset Index) via <code>NvM_SetDataIndex</code>.</li>\n<li>Der Zugriff auf ROM-Bereiche erfolgt im Dataset-Kontext bei Indizes im Bereich von <code>NVM_NV_BLOCK_NUM</code> bis <code>NVM_NV_BLOCK_NUM + NVM_ROM_BLOCK_NUM - 1</code> (während Indizes von <code>0</code> bis <code>NVM_NV_BLOCK_NUM - 1</code> für NV-Blöcke reserviert sind).</li>\n<li>Leseoperationen (<code>NvM_ReadBlock</code> bzw. <code>NvM_RestoreBlockDefaults</code>) greifen bei entsprechend gesetztem Index auf das zugeordnete ROM-Abbild zurück, um Standardwerte bereitzustellen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normative Festlegung des linearen Indizierungsschemas für Dataset-NVRAM-Blöcke mit Default-ROM-Daten.</li>\n<li>Konfigurationsparameter <code>NVM_NV_BLOCK_NUM</code> bestimmt die Anzahl der persistenten Datensätze im NV-Speicher und dient gleichzeitig als Basisversatz für die ROM-Blöcke.</li>\n<li><code>NVM_ROM_BLOCK_NUM</code> definiert die Anzahl der optionalen ROM-Blöcke. Ist <code>NVM_ROM_BLOCK_NUM == 0</code>, entfällt der gezeigte ROM-Bereich vollständig.</li>\n<li>Software-Entwickler müssen sicherstellen, dass übergebene Indizes innerhalb des Gesamtbereichs <code>[0, NVM_NV_BLOCK_NUM + NVM_ROM_BLOCK_NUM - 1]</code> liegen; Zugriffe außerhalb führen zu Laufzeitfehlern (z. B. <code>NVM_E_PARAM_DATA</code>).</li>\n</ul>"}, {"id": "FIG-8e1363554dfbe7e1", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm zur Darstellung des logischen Speicher-Layouts und der Adressierung von Datensätzen (Dataset NVRAM Block) im AUTOSAR NVRAM Manager (NvM). Das Schaubild veranschaulicht die logische Gruppierung und Indizierung der optionalen ROM-Block-Datenbereiche eines Dataset-Blocks, losgelöst von der physikalischen Speicherorganisation im nichtflüchtigen Speicher.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>ROM block data area NVM_NV_BLOCK_NUM (opt)</strong>: Erster optionaler Festwertspeicherbereich (Default-/Fallback-Daten) des Dataset-Blocks, adressiert über den Startindex <code>NVM_NV_BLOCK_NUM</code>.</li>\n<li><strong>ROM block data area (NVM_NV_BLOCK_NUM+NVM_ROM_BLOCK_NUM-1) (opt)</strong>: Letzter optionaler ROM-Datenbereich des Dataset-Blocks.</li>\n<li><strong>Indexspanne (<code>index NVM_NV_BLOCK_NUM to NVM_NV_BLOCK_NUM+NVM_ROM_BLOCK_NUM-1</code>)</strong>: Vertikaler Maß- bzw. Adressierungsvektor, der den gültigen Indexbereich für die Adressierung der ROM-Datensätze über die NvM-Dataset-Schnittstelle definiert.</li>\n<li><strong>Auslassungspunkte (<code>. . .</code>)</strong>: Symbolisieren dazwischenliegende, fortlaufend nummerierte ROM-Blöcke.</li>\n<li><strong>Gestrichelter Rahmen</strong>: Logische Umklammerung bzw. Clusterung der optionalen ROM-Blöcke innerhalb des Gesamt-Dataset-NVRAM-Blocks.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Adressierung eines spezifischen ROM-Datensatzes über den Datensatz-Index (Dataset Index) via <code>NvM_SetDataIndex</code>.</li>\n<li>Der Zugriff auf ROM-Bereiche erfolgt im Dataset-Kontext bei Indizes im Bereich von <code>NVM_NV_BLOCK_NUM</code> bis <code>NVM_NV_BLOCK_NUM + NVM_ROM_BLOCK_NUM - 1</code> (während Indizes von <code>0</code> bis <code>NVM_NV_BLOCK_NUM - 1</code> für NV-Blöcke reserviert sind).</li>\n<li>Leseoperationen (<code>NvM_ReadBlock</code> bzw. <code>NvM_RestoreBlockDefaults</code>) greifen bei entsprechend gesetztem Index auf das zugeordnete ROM-Abbild zurück, um Standardwerte bereitzustellen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Normative Festlegung des linearen Indizierungsschemas für Dataset-NVRAM-Blöcke mit Default-ROM-Daten.</li>\n<li>Konfigurationsparameter <code>NVM_NV_BLOCK_NUM</code> bestimmt die Anzahl der persistenten Datensätze im NV-Speicher und dient gleichzeitig als Basisversatz für die ROM-Blöcke.</li>\n<li><code>NVM_ROM_BLOCK_NUM</code> definiert die Anzahl der optionalen ROM-Blöcke. Ist <code>NVM_ROM_BLOCK_NUM == 0</code>, entfällt der gezeigte ROM-Bereich vollständig.</li>\n<li>Software-Entwickler müssen sicherstellen, dass übergebene Indizes innerhalb des Gesamtbereichs <code>[0, NVM_NV_BLOCK_NUM + NVM_ROM_BLOCK_NUM - 1]</code> liegen; Zugriffe außerhalb führen zu Laufzeitfehlern (z. B. <code>NVM_E_PARAM_DATA</code>).</li>\n</ul>"}], "trans": [{"from": "FIG-19ed18a3eb8973de", "to": "FIG-8e1363554dfbe7e1", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
